package vn.gastroai.be.application.auth; import io.jsonwebtoken.Claims; import org.springframework.security.authentication.BadCredentialsException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.gastroai.be.application.commands.LoginCommand; import vn.gastroai.be.application.readmodel.AuthResult; import vn.gastroai.be.domain.auth.*; import vn.gastroai.be.infrastructure.persistence.postgres.*; import vn.gastroai.be.infrastructure.security.JwtService; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*; @Service public class AuthService { private final PatientRepository patients; private final RevokedTokenRepository revoked; private final PasswordEncoder encoder; private final JwtService jwt; private final EmailVerificationService mail; public AuthService(PatientRepository p,RevokedTokenRepository r,PasswordEncoder e,JwtService j,EmailVerificationService m){patients=p;revoked=r;encoder=e;jwt=j;mail=m;} @Transactional("postgresTransactionManager") public void register(String email,String password,String name){String normalized=email.trim().toLowerCase();if(patients.findByEmail(normalized).isPresent())throw new IllegalStateException("Email da duoc su dung");String raw=UUID.randomUUID().toString()+UUID.randomUUID();Patient p=new Patient();p.setEmail(normalized);p.setPasswordHash(encoder.encode(password));p.setFullName(name.trim());p.setRole(UserRole.PATIENT);p.setVerificationTokenHash(hash(raw));p.setVerificationTokenExpiresAt(Instant.now().plus(24,java.time.temporal.ChronoUnit.HOURS));patients.save(p);mail.send(normalized,raw);} @Transactional("postgresTransactionManager") public void verify(String token){Patient p=patients.findByVerificationTokenHash(hash(token)).orElseThrow(()->new IllegalArgumentException("Token xac thuc khong hop le"));if(p.getVerificationTokenExpiresAt().isBefore(Instant.now()))throw new IllegalArgumentException("Token xac thuc da het han");p.setEmailVerified(true);p.setVerificationTokenHash(null);p.setVerificationTokenExpiresAt(null);} public AuthResult login(LoginCommand c){Patient p=patients.findByEmail(c.email().trim().toLowerCase()).orElseThrow(()->new BadCredentialsException("Email hoac mat khau khong dung"));if(!encoder.matches(c.password(),p.getPasswordHash()))throw new BadCredentialsException("Email hoac mat khau khong dung");if(!p.isEmailVerified())throw new IllegalStateException("Email chua duoc xac thuc");return result(p);} @Transactional("postgresTransactionManager") public void logout(String token){Claims c=jwt.parse(token);revoked.save(new RevokedToken(c.getId(),c.getExpiration().toInstant(),Instant.now()));} @Transactional("postgresTransactionManager") public void changePassword(Long id,String oldPass,String newPass){Patient p=patients.findById(id).orElseThrow(()->new BadCredentialsException("Tai khoan khong ton tai"));if(!encoder.matches(oldPass,p.getPasswordHash()))throw new BadCredentialsException("Mat khau hien tai khong dung");if(encoder.matches(newPass,p.getPasswordHash()))throw new IllegalArgumentException("Mat khau moi phai khac mat khau hien tai");p.setPasswordHash(encoder.encode(newPass));p.setTokenVersion(p.getTokenVersion()+1);} private AuthResult result(Patient p){return new AuthResult(jwt.generateToken(p),p.getId(),p.getEmail(),p.getFullName(),p.getRole().name());} private static String hash(String value){try{byte[] b=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));return HexFormat.of().formatHex(b);}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} }
